  // sens 2, le nom → formule semi-développée, groupe entouré, nom du groupe, famille
  function famille(id, competence, cle, du, groupe, familles) {
    const rep = `${fig(F[cle + 'R'])}<p><b>${groupe}</b> (${familles})</p>`;
    return { id, type: 'savoir', competence, statut: 'nouvelle', outils: ['crayon'], faces: [
      { q: `${fig(F[cle])}<p>À quelle famille appartient cette molécule ? Entoure son groupe caractéristique et donne son nom.</p>`, r: rep },
      { q: `<p>Écris la formule semi-développée ${du}. Entoure son groupe caractéristique ; donne son nom et la famille.</p>`, r: rep },
    ] };
  }

